// UI strings: English or French (the browser's language on a first load, then the sidebar toggle). DOM-free so node
// can test it: storage, navigator and
// <html lang> are only touched when a `window` exists. Every user-visible string goes through t(); the French
// dictionary must hold exactly the English keys (checked by the type of `fr`, and by client/test/i18n.test.ts).
// Plurals: separate `<key>_one` / `<key>_other` keys picked with Intl.PluralRules (French says "1 chantier", "0 chantier").

export type Lang = 'en' | 'fr';
export const LANGS: readonly Lang[] = ['en', 'fr'];
