export const DICTS: Record<Lang, Record<Key, string>> = { en, fr };

export type Params = Record<string, string | number>;
/** Keys that come as a `_one` / `_other` pair. */
export type PluralBase = { [K in Key]: K extends `${infer B}_one` ? (`${B}_other` extends Key ? B : never) : never }[Key];

export const isLang = (v: unknown): v is Lang => v === 'en' || v === 'fr';
export const hasKey = (k: string): k is Key => Object.hasOwn(en, k);

/** Pure lookup: the language, then English, then the key itself (never an empty label). {name} replaced by params.name. */
export function translate(l: Lang, key: Key, params?: Params): string {
  const s = DICTS[l]?.[key] ?? en[key] ?? key;
  return params ? s.replace(/\{(\w+)\}/g, (m, k: string) => k in params ? String(params[k]) : m) : s;
}

// Browser only: node (tests) has no window, and touching its localStorage prints a warning.
const store = (): Storage | null => { try { return typeof window === 'undefined' ? null : window.localStorage; } catch { return null; } };
const applyDoc = (l: Lang) => { if (typeof document !== 'undefined') document.documentElement.lang = l; };

/** Language of a first load: the one stored by the EN/FR toggle, else the first browser language the UI knows
 *  (`fr-CA` → fr, `de` then `fr` → fr), else English. Pure: the caller passes storage and `navigator.languages`. */
export function initialLang(stored: unknown, prefs: readonly string[]): Lang {
  if (isLang(stored)) return stored;
  for (const p of prefs) { const base = p.toLowerCase().split('-')[0]; if (isLang(base)) return base; }
  return 'en';
}
// Browser only, like store(): node has a `navigator` too, whose locale would make the tests depend on the machine.
const browserLangs = (): readonly string[] => typeof window === 'undefined' ? [] : navigator.languages?.length ? navigator.languages : [navigator.language ?? ''];

let current: Lang = initialLang(store()?.getItem(LANG_KEY), browserLangs());
applyDoc(current);

export const lang = (): Lang => current;
/** Changes the language for this tab and the next loads; the caller re-renders. */
export function setLang(l: Lang) { current = l; try { store()?.setItem(LANG_KEY, l); } catch { /* private mode: this tab only */ } applyDoc(l); }

export const t = (key: Key, params?: Params) => translate(current, key, params);
/** Count: `<base>_one` or `<base>_other` by the plural rule of the language; {n} = the count. */
export function tn(base: PluralBase, n: number, params: Params = {}): string {
  const one = new Intl.PluralRules(current).select(n) === 'one';
  return t(`${base}_${one ? 'one' : 'other'}` as Key, { n, ...params });
}
/** Ordinal (place in a queue): 1st, 2nd, 3rd, 4th / 1er, 2e. */
export function ordinal(n: number): string {
  const r = new Intl.PluralRules(current, { type: 'ordinal' }).select(n);
  return t(r === 'one' ? 'nth_one' : r === 'two' ? 'nth_two' : r === 'few' ? 'nth_few' : 'nth_other', { n });
}
/** Quoted title, with the typography of the language (“…” / « … »). */
export const quote = (text: string) => t('quote', { text });
